+class ContactFormValidator {
+  constructor(formId) {
+    this.form = document.getElementById(formId);
+    this.fields = {
+      fullname: {
+        element: document.getElementById('fullname'),
+        errorElement: document.getElementById('fullname-error'),
+        validate: this.validateFullname.bind(this),
+      },
+      email: {
+        element: document.getElementById('email'),
+        errorElement: document.getElementById('email-error'),
+        validate: this.validateEmail.bind(this),
+      },
+      phone: {
+        element: document.getElementById('phone'),
+        errorElement: document.getElementById('phone-error'),
+        validate: this.validatePhone.bind(this),
+      },
+    };
+
+    this.init();
+  }
+
+  init() {
+    this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+
+    Object.values(this.fields).forEach((field) => {
+      field.element.addEventListener('blur', () => this.validateField(field));
+      field.element.addEventListener('change', () => this.validateField(field));
+      field.element.addEventListener('input', () => this.clearError(field));
+    });
+  }
+
+  validateField(field) {
+    const error = field.validate();
+    if (error) {
+      this.setError(field, error);
+    } else {
+      this.clearError(field);
+    }
+  }
+
+  validateFullname() {
+    const value = this.fields.fullname.element.value.trim();
+    if (!value) {
+      return 'Error: Full name is required.';
+    }
+    if (value.length < 2) {
+      return 'Error: Full name must be at least 2 characters.';
+    }
+    return null;
+  }
+
+  validateEmail() {
+    const value = this.fields.email.element.value.trim();
+    if (!value) {
+      return 'Error: Email address is required.';
+    }
+    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+    if (!emailRegex.test(value)) {
+      return 'Error: Enter a valid email like name@example.com.';
+    }
+    return null;
+  }
+
+  validatePhone() {
+    const value = this.fields.phone.element.value.trim();
+    if (!value) {
+      return null;
+    }
+    const phoneRegex = /^(\(\d{3}\)\s?\d{3}-\d{4}|\d{3}-\d{3}-\d{4}|\d{10}|(\+\d{1,3}\s?)?\d{1,14})$/;
+    if (!phoneRegex.test(value)) {
+      return 'Error: Enter a valid phone number like (123) 456-7890 or 123-456-7890.';
+    }
+    return null;
+  }
+
+  setError(field, errorMessage) {
+    field.element.setAttribute('aria-invalid', 'true');
+    field.errorElement.textContent = errorMessage;
+  }
+
+  clearError(field) {
+    field.element.setAttribute('aria-invalid', 'false');
+    field.errorElement.textContent = '';
+  }
+
+  validateAll() {
+    let firstInvalidField = null;
+    let hasErrors = false;
+
+    Object.values(this.fields).forEach((field) => {
+      const error = field.validate();
+      if (error) {
+        this.setError(field, error);
+        if (!firstInvalidField) {
+          firstInvalidField = field.element;
+        }
+        hasErrors = true;
+      } else {
+        this.clearError(field);
+      }
+    });
+
+    if (firstInvalidField) {
+      firstInvalidField.focus();
+    }
+
+    return !hasErrors;
+  }
+
+  handleSubmit(e) {
+    e.preventDefault();
+
+    if (this.validateAll()) {
+      this.showSuccessMessage();
+      this.form.reset();
+      Object.values(this.fields).forEach((field) => {
+        this.clearError(field);
+      });
+    }
+  }
+
+  showSuccessMessage() {
+    const successElement = document.getElementById('success-message');
+    successElement.textContent = 'Thank you! We\'ve received your message and will get back to you soon.';
+    successElement.classList.add('show');
+
+    setTimeout(() => {
+      successElement.classList.remove('show');
+      successElement.textContent = '';
+    }, 5000);
+  }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+  new ContactFormValidator('contact-form');
+});
+
")

